contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when a non-owner (this contract) tries to call withdraw or sendMoney,
    // the calls revert (onlyOwner) and do not change the contract balance. The deployer of c
    // is the account that deployed c (not this test), so this contract is not the owner.

    function run(address payable target, uint value, bytes memory data, uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient balance for deposit");

        // Deposit some Ether into c by sending to its fallback (which increments depositsCount).
        // Use c.call to trigger fallback: but must call through c with value — call through payable fallback
        // The fallback is external payable, so a direct low-level call from this test will send Ether.
        (bool okDeposit, ) = address(c).call{value: deposit}("");
        // allow deposit to succeed or fail; read balance before attempting withdraw/sendMoney
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt withdrawAll (should revert because onlyOwner). Capture revert.
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Attempt withdraw specific amount
        bool revertedWithdraw;
        try c.withdraw(value) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Attempt sendMoney to arbitrary target
        bool revertedSend;
        try c.sendMoney(target, value, data) {
            revertedSend = false;
        } catch {
            revertedSend = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule (assert): If this contract is not the owner, then any of the three owner-only calls
        // must revert, and the contract balance must remain unchanged by them. Also depositsCount only
        // changes as a result of the deposit call above (i.e., at most +1 compared to before if deposit succeeded).
        // We cannot directly check owner, but since the checker deploys a fresh c with owner = deployer (not this),
        // we assert that at least one of the owner-only calls reverted and that none decreased the contract balance.

        // Formulate: afterBalance == beforeBalance (owner-only calls did not change balance), and
        // if deposit low-level call succeeded then depositsCount increased by at most 1, else unchanged,
        // and at least one of the owner-only operations reverted (ensures assertion is nontrivial).

        bool depositEffectOk = true;
        if (okDeposit) {
            // fallback increments depositsCount by 1 on success
            depositEffectOk = (afterDeposits == beforeDeposits + 1);
        } else {
            depositEffectOk = (afterDeposits == beforeDeposits);
        }

        assert(afterBalance == beforeBalance && depositEffectOk && (revertedWithdrawAll || revertedWithdraw || revertedSend));
    }

    receive() external payable {}
}

