        require(address(this).balance >= value && address(this).balance >= directAmount);

        // read initial depositsCount and contract balance
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // make a sendMoney call from owner (this contract is the owner), possibly sending value to target
        // This is a state-changing call and must be a top-level statement
        c.sendMoney(target, value, data);

        // read after sendMoney
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // Now send Ether directly to c to invoke its fallback and increase depositsCount.
        // Use a low-level call from this contract to c with directAmount wei
        (bool ok, ) = address(c).call{value: directAmount}("");
        // We don't require ok; fallback may accept or the call may succeed/fail depending on gas or target, but C's fallback is payable and increments depositsCount on successful receipt.

        uint finalCount = c.depositsCount();
        uint finalBal = address(c).balance;

        // General rule to assert:
        // 1) The sendMoney call performed by owner does not change depositsCount (it may change c's balance only if target==address(c) and value>0, but depositsCount should remain same).
