        // However we cannot use the tuple ok here because it's a local; we have ok. Use it in assert.

        assert(
            // sendMoney didn't change depositsCount
            afterCount == beforeCount
            // and finalCount is either unchanged if direct call failed or increased by exactly 1 when direct call succeeded and balance rose by directAmount
            && ( (ok && finalCount == afterCount + 1 && finalBal == afterBal + directAmount) || (!ok && finalCount == afterCount && finalBal == afterBal) )
        );
    }

    receive() external payable { }
}

